"""Self-contained prediction-blind annotation interface."""

BLIND_REVIEWER_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>ABREX blind annotation</title>
<style>
:root{--ink:#17202a;--muted:#596776;--line:#d9e0e6;--paper:#fff;--bg:#f3f5f7;--nav:#173f4f;--blue:#176b87;--sf:#ffe08a;--lf:#bde9dc;--danger:#8b2f2f}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}header{background:var(--nav);color:#fff;padding:16px 24px}.app{display:grid;grid-template-columns:230px minmax(0,1fr) 360px;gap:16px;max-width:1500px;margin:auto;padding:16px}.panel{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:16px}.sidebar{max-height:calc(100vh - 110px);overflow:auto;position:sticky;top:12px}button,.button{border:0;border-radius:6px;background:var(--blue);color:#fff;padding:9px 12px;font-weight:650;cursor:pointer;text-decoration:none}button.ghost,.button.ghost{background:#eaf0f3;color:#24333d}button.secondary,.button.secondary{background:#687783}button.danger{background:var(--danger)}button:disabled{opacity:.55;cursor:not-allowed}.case{display:block;width:100%;background:#fff;color:var(--ink);text-align:left;margin:2px 0;border-left:4px solid transparent}.case.active{background:#dceef3;border-left-color:var(--blue)}.case.complete::after{content:' ✓';color:#187044}.row,.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.passage{white-space:pre-wrap;font:18px/1.85 Georgia,serif;border:2px solid #91a8b3;border-radius:8px;padding:18px;margin:10px 0}.sf{background:var(--sf);border-bottom:3px solid #bc8500}.lf{background:var(--lf);border-bottom:3px solid #14725a}.both{background:linear-gradient(135deg,var(--sf) 50%,var(--lf) 50%)}.muted{color:var(--muted)}.context,.structure{white-space:pre-wrap;background:#f4f6f7;padding:10px;border-radius:6px;margin:8px 0}.relation{border:1px solid var(--line);border-radius:8px;padding:10px;margin:8px 0}.field{display:block;margin:9px 0}.field input,.field textarea,.field select{display:block;width:100%;border:1px solid #aebbc3;border-radius:6px;padding:8px;font:inherit}.selection,.status{padding:9px;border-radius:6px;background:#edf3f5;margin:8px 0}.status.ok{background:#e4f4e9;color:#155b2c}.status.error{background:#fff0dc;color:#713f08}.hidden{display:none!important}.search{border:1px solid var(--line);border-radius:8px;padding:10px;margin:12px 0}.locked{border:2px solid #187044}.file-label{display:inline-block}@media(max-width:1000px){.app{grid-template-columns:1fr}.sidebar{position:static;max-height:none}.case-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}}@media(max-width:520px){header{padding:12px}.app{padding:8px}.panel{padding:11px}.passage{font-size:17px}.actions button,.actions .button{width:100%}}
</style></head><body>
<header><h1 id="workflow">ABREX prediction-blind annotation</h1><div id="meta">Loading source packet…</div></header>
<div class="app">
<aside class="panel sidebar"><strong>Passages</strong><p id="progress" class="muted"></p><div class="row"><button id="needs" class="ghost">Needs attention</button><button id="all" class="ghost">All</button></div><div id="case-list" class="case-list"></div></aside>
<main class="panel"><div class="row"><button id="previous" class="ghost">Previous</button><button id="next" class="ghost">Next</button><span id="position" class="muted"></span></div><h2 id="title"></h2><div id="source" class="muted"></div><p><strong>Find every in-scope abbreviation definition in the passage. Select exact source text; do not annotate the title or surrounding context.</strong></p><div id="passage" class="passage" tabindex="0"></div><details><summary>Permitted surrounding context (not annotatable)</summary><div id="context" class="context"></div></details><details id="structure-details"><summary>Table/list structure</summary><div id="structures"></div></details><h3>Recorded relations</h3><div id="relations"></div></main>
<aside class="panel"><h2>Annotation</h2><div id="readiness" class="status">Checking progress…</div><div id="save-status" class="status">No unsaved changes.</div><div class="search"><strong>Passage-search completion</strong><label class="field"><input id="searched" type="checkbox"> Searched this entire passage; every in-scope definition is recorded. If there are no relations, this means “Searched this passage; no in-scope definition found.”</label><label class="field">Search note<select id="search-note"><option value="none">Complete</option><option value="missed">Not yet complete</option><option value="unsure">Uncertain</option></select></label></div><h3>Add or edit a relation</h3><p class="muted">Select text in the passage. Repeated strings are distinguished by exact position.</p><div id="selection" class="selection">No text selected.</div><div class="row"><button id="use-sf" class="ghost">Use as short form</button><button id="use-lf" class="ghost">Use as long form</button><button id="add-evidence" class="ghost">Add evidence fragment</button></div><div id="fragments"></div><label class="field">Short form<input id="sf" readonly></label><label class="field">Long form<input id="lf" readonly></label><label class="field">Relation kind<select id="kind"><option value="uncertain">Uncertain</option><option value="abbreviation_expansion">Abbreviation expansion</option><option value="other_naming_or_code_relation">Other naming/code relation</option></select></label><label class="field">Evidence structure<select id="evidence"><option value="uncertain">Uncertain</option><option value="contiguous_shared">Contiguous/shared</option><option value="discontinuous">Discontinuous</option></select></label><label class="field">Required context<select id="required-context"><option value="uncertain">Uncertain</option><option value="text_alone">Text alone</option><option value="document_structure">Document structure</option><option value="image">Image</option></select></label><label class="field">Interpretation (not a quotation)<input id="interpretation"></label><label><input id="source-error" type="checkbox"> Possible source error</label><label class="field">Relation note<textarea id="relation-note" rows="2"></textarea></label><div class="row"><button id="add">Add relation</button><button id="apply">Apply edit</button><button id="clear" class="secondary">Clear editor</button></div><label class="field">Passage notes<textarea id="notes" rows="3"></textarea></label><div class="actions"><button id="save">Save draft</button><button id="save-next">Save and next</button><a class="button secondary" href="/api/export/json">JSON backup</a><label class="button secondary file-label">Import JSON<input id="import-json" class="hidden" type="file" accept="application/json"></label></div><hr><div class="actions"><button id="lock" class="danger">Lock completed annotation</button><a id="locked-export" class="button secondary hidden" href="/api/export/locked">Export locked package</a></div><p class="muted">Locking is irreversible for this file. Later correction requires a new version and an exposure record.</p></aside>
</div><script>
'use strict';
const byId=id=>document.getElementById(id);const cpSlice=(t,s,e)=>Array.from(t).slice(s,e).join('');let packet,state,lock,index=0,filter='needs',draft,editor={},selected=null,editing=null,dirty=false,saving=false;
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}function clear(n){while(n.firstChild)n.removeChild(n.firstChild)}function annotation(c){return state.annotations[c.case_id]||null}function snapshot(c){return structuredClone(annotation(c)?.current||{pairs:[],missed_definition:'unreviewed',notes:''})}function complete(c){return snapshot(c).missed_definition==='none'}function visible(){return packet.cases.map((c,n)=>({c,n})).filter(x=>filter==='all'||!complete(x.c))}function banner(message,kind='ok'){const n=byId('save-status');n.textContent=message;n.className='status '+kind}function markDirty(){dirty=true;banner('Unsaved changes.','error')}
function renderList(){const h=byId('case-list');clear(h);visible().forEach(({c,n})=>{const b=node('button',(n+1)+'. '+c.title,'case'+(n===index?' active':'')+(complete(c)?' complete':''));b.onclick=async()=>{if(n===index||await saveIfDirty())show(n)};h.appendChild(b)});const done=packet.cases.filter(complete).length;byId('progress').textContent=done+' complete · '+(packet.cases.length-done)+' need attention'}
function segments(c){const spans=draft.pairs.flatMap(p=>[{...p.short_form,role:'sf'},{...p.long_form,role:'lf'}]).filter(x=>x.start!==undefined);const bounds=[0,Array.from(c.text).length,...spans.flatMap(s=>[s.start,s.end])].sort((a,b)=>a-b),unique=[...new Set(bounds)];return unique.slice(0,-1).map((start,i)=>{const end=unique[i+1],roles=new Set(spans.filter(s=>s.start<end&&s.end>start).map(s=>s.role));return{start,end,roles}})}
function renderPassage(c){const h=byId('passage');clear(h);segments(c).forEach(s=>{const text=cpSlice(c.text,s.start,s.end);if(!s.roles.size)h.appendChild(document.createTextNode(text));else h.appendChild(node('mark',text,s.roles.size===2?'both':[...s.roles][0]))})}
function renderRelations(){const h=byId('relations');clear(h);draft.pairs.forEach((p,n)=>{const box=node('div',undefined,'relation'),label=(p.long_form?.text||'—')+' → '+(p.short_form?.text||'—');box.append(node('strong',label),node('p','Kind: '+p.relation_kind.replaceAll('_',' ')+' · Evidence: '+p.evidence_structure.replaceAll('_',' ')+' · Context: '+p.context_requirement.replaceAll('_',' '),'muted'));const edit=node('button','Edit','ghost');edit.onclick=()=>loadEditor(p);const remove=node('button','Remove','ghost');remove.onclick=()=>{draft.pairs.splice(n,1);markDirty();render()};box.append(edit,remove);h.appendChild(box)});if(!draft.pairs.length)h.appendChild(node('p','No relations recorded.','muted'))}
function renderStructures(c){const h=byId('structures');clear(h);c.structures.forEach(s=>h.appendChild(node('div',s.kind+': '+s.text,'structure')));byId('structure-details').classList.toggle('hidden',!c.structures.length)}
function renderEditor(){byId('sf').value=editor.short_form?.text||'';byId('lf').value=editor.long_form?.text||'';byId('kind').value=editor.relation_kind||'uncertain';byId('evidence').value=editor.evidence_structure||'uncertain';byId('required-context').value=editor.context_requirement||'uncertain';byId('interpretation').value=editor.interpretation||'';byId('source-error').checked=Boolean(editor.source_error);byId('relation-note').value=editor.notes||'';const h=byId('fragments');clear(h);(editor.evidence_spans||[]).forEach((s,i)=>{const r=node('div','Evidence '+(i+1)+': “'+s.text+'” ','muted'),b=node('button','Remove','ghost');b.onclick=()=>{editor.evidence_spans.splice(i,1);markDirty();renderEditor()};r.appendChild(b);h.appendChild(r)})}
function render(){const c=packet.cases[index];byId('title').textContent=c.title;const source=byId('source');clear(source);source.append(document.createTextNode((c.arm==='pmc_cc_by'?'Full text':'Abstract')+' · '+c.section_heading+' · '));const a=node('a','Open source');a.href=c.source_url;a.target='_blank';a.rel='noreferrer';source.appendChild(a);byId('position').textContent=(index+1)+' of '+packet.cases.length;byId('context').textContent=[c.context_before,c.context_after].filter(Boolean).join('\n\n[Passage]\n\n');byId('notes').value=draft.notes;byId('searched').checked=draft.missed_definition==='none';byId('search-note').value=draft.missed_definition==='unreviewed'?'missed':draft.missed_definition;renderPassage(c);renderRelations();renderStructures(c);renderEditor();renderList();const locked=Boolean(lock?.locked);document.querySelectorAll('button,input,textarea,select').forEach(x=>x.disabled=locked);byId('locked-export').classList.toggle('hidden',!locked);if(locked)document.body.classList.add('locked')}
function show(n){index=n;draft=snapshot(packet.cases[n]);editor={evidence_spans:[]};editing=null;selected=null;dirty=false;banner('Loaded. Save draft writes changes to disk.');render();history.replaceState(null,'','#case='+encodeURIComponent(packet.cases[n].case_id))}
function offsets(){const s=window.getSelection(),h=byId('passage');if(!s||s.rangeCount!==1||s.isCollapsed)return null;const r=s.getRangeAt(0);if(!h.contains(r.commonAncestorContainer))return null;const p=r.cloneRange();p.selectNodeContents(h);p.setEnd(r.startContainer,r.startOffset);const start=Array.from(p.toString()).length,text=r.toString(),end=start+Array.from(text).length;if(!text||cpSlice(packet.cases[index].text,start,end)!==text)return null;return{start,end,text}}
function capture(){selected=offsets();byId('selection').textContent=selected?'Selected: “'+selected.text+'”':'No text selected.'}function assign(role){selected=selected||offsets();if(!selected)return banner('Select exact passage text first.','error');editor[role]=selected;renderEditor()}function overlap(a,b){return a&&b&&a.start<b.end&&b.start<a.end}function addEvidence(){selected=selected||offsets();if(!selected)return banner('Select exact passage text first.','error');editor.evidence_spans=editor.evidence_spans||[];if([editor.short_form,editor.long_form,...editor.evidence_spans].some(x=>overlap(x,selected)))return banner('Evidence fragments cannot overlap.','error');editor.evidence_spans.push(selected);editor.evidence_spans.sort((a,b)=>a.start-b.start);selected=null;renderEditor()}
function fields(){return{relation_kind:byId('kind').value,evidence_structure:byId('evidence').value,context_requirement:byId('required-context').value,interpretation:byId('interpretation').value,source_error:byId('source-error').checked,evidence_spans:editor.evidence_spans||[],notes:byId('relation-note').value}}function validateEditor(){if(!editor.short_form||!editor.long_form){banner('Both exact endpoints are required.','error');return false}if(byId('evidence').value==='discontinuous'&&!(editor.evidence_spans||[]).length){banner('Add at least one evidence fragment for discontinuous evidence.','error');return false}return true}function relationStatus(f){return[f.relation_kind,f.evidence_structure,f.context_requirement].includes('uncertain')?'unsure':'correct'}
function addRelation(){if(!validateEditor())return;const f=fields();draft.pairs.push({decision_id:'added-'+crypto.randomUUID(),suggestion_id:null,proposal_kind:'definition',status:relationStatus(f),short_form:editor.short_form,long_form:editor.long_form,origin:'added',...f});editor={evidence_spans:[]};markDirty();render()}function loadEditor(p){editing=p.decision_id;editor=structuredClone(p);renderEditor();byId('kind').focus()}function applyEdit(){if(!editing)return banner('Choose Edit on a recorded relation first.','error');if(!validateEditor())return;const p=draft.pairs.find(x=>x.decision_id===editing),f=fields();Object.assign(p,{short_form:editor.short_form,long_form:editor.long_form,status:relationStatus(f),...f});editing=null;editor={evidence_spans:[]};markDirty();render()}function clearEditor(){editing=null;editor={evidence_spans:[]};selected=null;byId('selection').textContent='No text selected.';renderEditor()}
async function json(response){let body;try{body=await response.json()}catch{throw Error('Unreadable local response')}if(!response.ok)throw Error(body.error||'Request failed');return body}async function readiness(){const r=await json(await fetch('/api/readiness')),n=byId('readiness');n.textContent=r.complete?'All passages are ready to lock.':r.remaining_cases+' passages need attention; '+r.remaining_items+' required items remain.';n.className='status '+(r.complete?'ok':'error')}
async function save(next=false){if(saving||lock?.locked)return false;saving=true;try{draft.notes=byId('notes').value;const c=packet.cases[index],a=annotation(c),body={schema_version:'t052-annotation-submission-v2',packet_id:packet.packet_id,packet_content_sha256:packet.content_sha256,current_case_id:c.case_id,annotations:{[c.case_id]:{expected_revision:a?a.revision:0,decision:draft}}};state=await json(await fetch('/api/annotations',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}));dirty=false;banner('Draft saved durably.');await readiness();renderList();if(next){const candidates=packet.cases.map((x,n)=>({x,n})).filter(x=>x.n!==index&&!complete(x.x));if(candidates.length)show(candidates[0].n)}return true}catch(e){banner('Save failed: '+e.message,'error');return false}finally{saving=false}}async function saveIfDirty(){return dirty?save(false):true}async function navigate(delta){if(!(await saveIfDirty()))return;show((index+delta+packet.cases.length)%packet.cases.length)}
async function importJson(file){if(!file)return;try{state=await json(await fetch('/api/import/json',{method:'POST',headers:{'Content-Type':'application/json'},body:await file.arrayBuffer()}));show(index);await readiness();banner('Backup imported and saved.')}catch(e){banner('Import failed: '+e.message,'error')}}async function lockNow(){if(dirty&&!await save(false))return;if(!confirm('Lock this completed annotation state? This file cannot be edited afterward.'))return;try{lock=await json(await fetch('/api/lock',{method:'POST'}));render();banner('Annotation locked. Export the locked package.')}catch(e){banner('Lock failed: '+e.message,'error')}}
async function init(){try{packet=await json(await fetch('/api/packet'));state=await json(await fetch('/api/annotations'));lock=await json(await fetch('/api/lock'));byId('workflow').textContent=packet._workflow.name;byId('meta').textContent=packet.cases.length+' source passages · '+packet.packet_id+' · no evaluated outputs exposed';const wanted=new URLSearchParams(location.hash.slice(1)).get('case')||state.current_case_id,found=packet.cases.findIndex(c=>c.case_id===wanted);show(found>=0?found:0);await readiness()}catch(e){banner('Load failed: '+e.message,'error')}}
byId('passage').addEventListener('mouseup',capture);byId('passage').addEventListener('keyup',capture);byId('use-sf').onclick=()=>assign('short_form');byId('use-lf').onclick=()=>assign('long_form');byId('add-evidence').onclick=addEvidence;byId('add').onclick=addRelation;byId('apply').onclick=applyEdit;byId('clear').onclick=clearEditor;byId('searched').onchange=()=>{draft.missed_definition=byId('searched').checked?'none':'missed';byId('search-note').value=draft.missed_definition;markDirty()};byId('search-note').onchange=()=>{draft.missed_definition=byId('search-note').value;byId('searched').checked=draft.missed_definition==='none';markDirty()};byId('notes').oninput=markDirty;byId('save').onclick=()=>save(false);byId('save-next').onclick=()=>save(true);byId('previous').onclick=()=>navigate(-1);byId('next').onclick=()=>navigate(1);byId('needs').onclick=()=>{filter='needs';renderList()};byId('all').onclick=()=>{filter='all';renderList()};byId('import-json').onchange=e=>importJson(e.target.files[0]);byId('lock').onclick=lockNow;document.addEventListener('keydown',e=>{if(e.altKey&&e.key.toLowerCase()==='s'){e.preventDefault();save(false)}if(e.altKey&&e.key.toLowerCase()==='n'){e.preventDefault();navigate(1)}if(e.altKey&&e.key.toLowerCase()==='a'){e.preventDefault();addRelation()}});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});init();
</script></body></html>"""

__all__ = ["BLIND_REVIEWER_HTML"]
